function useTranslator(lang) {
  return useMemo(() => {
    const idx = LANGS.indexOf(lang);
    const t = {};
    for (const key in STRINGS) t[key] = STRINGS[key][idx] ?? STRINGS[key][0];
    return t;
  }, [lang]);
}

