const fmtINR = (n) => "₹" + Number(n || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 });
const round2 = (n) => Math.round(n * 100) / 100;
const pad4 = (n) => String(n).padStart(4, "0");

/* stock helpers: rolls-based FIFO */
function stockOf(fabric) { return (fabric.rolls || []).reduce((s, r) => s + Number(r.qty || 0), 0); }
function deductFIFO(rolls, qty) {
  let remaining = qty;
  const next = [];
  for (const r of rolls) {
    if (remaining <= 0) { next.push(r); continue; }
    if (r.qty <= remaining) { remaining -= r.qty; continue; }
    next.push({ ...r, qty: round2(r.qty - remaining) });
    remaining = 0;
  }
  return next;
}
function priceFor(fab, qty) {
  const slabs = [...(fab.slabs || [])].sort((a, b) => b.minQty - a.minQty);
  const hit = slabs.find((s) => qty >= s.minQty);
  return hit ? hit.price : fab.retailPrice;
}
function taxSplit(taxable, gstRate, sameState) {
  const tax = round2(taxable * (gstRate || 0) / 100);
  if (sameState) {
    const cgst = round2(tax / 2);
    const sgst = round2(tax - cgst); // derive, don't round independently — keeps cgst+sgst === tax to the paisa
    return { cgst, sgst, igst: 0, tax };
  }
  return { cgst: 0, sgst: 0, igst: tax, tax };
}

